export default function CurrentTime() {
  // Anti-pattern example
  const time = new Date().toLocaleTimeString();
  return <span>{time}</span>;
}

import moment from 'moment'; // Heavy library
import { db } from '@/lib/db';

// This is a Server Component
export default async function TransactionHistory({ userId }) {
  const transactions = await db.query('SELECT * FROM tx WHERE user_id = ?', userId);

  return (
    <ul>
      {transactions.map(tx => (
        <li key={tx.id}>
          {moment(tx.date).format('MMMM Do YYYY, h:mm:ss a')}
          : ${tx.amount}
        </li>
      ))}
    </ul>
  );
}

